const $=s=>document.querySelector(s),API=window.GRADBEACON_API_BASE||"",S={job:null,snap:null,selected:new Set(),events:null,pjob:null,draft:null,decision:null};
const esc=v=>{const d=document.createElement("div");d.textContent=v??"";return d.innerHTML}, list=v=>(v||"").split(",").map(x=>x.trim()).filter(Boolean);
async function api(path,opt={}){const r=await fetch(API+path,{headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt}),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error?.message||`Request failed (${r.status})`);return j}
function fav(){try{return new Set(JSON.parse(localStorage.getItem("gradbeacon-favorites")||"[]"))}catch{return new Set()}} function saveFav(x){try{localStorage.setItem("gradbeacon-favorites",JSON.stringify([...x]))}catch{}}
function profile(){const f=$("#profile-form"),g=Number(f.gpa.value),b=Number(f.maxTuition.value);if(!f.degreePath.value||!f.field.value.trim()||!f.qualification.value.trim()||!Number.isFinite(g))throw Error("Complete required fields and enter a valid GPA.");const fundingMap={required:"need_full_funding",preferred:"prefer_funding",not_important:"not_required",unspecified:"unspecified"};return {degree_paths:f.degreePath.value==="both"?["masters","phd"]:[f.degreePath.value],field:f.field.value.trim(),qualification:f.qualification.value.trim(),qualification_status:f.qualificationStatus.value,gpa:{value:g,scale:f.gpaScale.value},destination_country:"US",research_interests:list(f.interests.value),skills:list(f.skills.value),funding_preference:fundingMap[f.funding.value]||f.funding.value,budget:Number.isFinite(b)&&b>0?{max_tuition_per_year_usd:b}:null}}
function saveProfile(){const f=$("#profile-form");if(!f.remember.checked)return;try{localStorage.setItem("gradbeacon-profile",JSON.stringify(Object.fromEntries(new FormData(f))))}catch{}}function restore(){try{const p=JSON.parse(localStorage.getItem("gradbeacon-profile"));Object.entries(p||{}).forEach(([k,v])=>{const e=$("#profile-form").elements.namedItem(k);if(e)e.type==="checkbox"?e.checked=!!v:e.value=v})}catch{}}
function rows(){return [...(S.snap?.groups||[]).flatMap(x=>x.results),...(S.snap?.fallback_results||[])]}function money(v){return v==null?"Not found":`$${Number(v).toLocaleString()} / year`}
function render(){const deg=$("#degree-filter").value,fun=$("#funding-filter").value,sort=$("#sort-results").value;let a=rows().filter(x=>(deg==="all"||x.program.degree_level===deg)&&(fun==="all"||x.match?.funding_class===fun));a.sort((x,y)=>sort==="fit"?(y.match?.overall_fit_score??-1)-(x.match?.overall_fit_score??-1):sort==="tuition-low"?(x.match?.sort_tuition_annual_usd??Infinity)-(y.match?.sort_tuition_annual_usd??Infinity):(y.match?.sort_tuition_annual_usd??-1)-(x.match?.sort_tuition_annual_usd??-1));const fs=fav();$("#result-summary").textContent=`${a.length} evidence-backed result${a.length===1?"":"s"} shown.`;$("#results").innerHTML=a.length?a.map(r=>{const p=r.program,m=r.match,pend=r.pending_decisions||[];return `<article class="card"><div class="card-top"><div><h3>${esc(p.program_name)}</h3><p class="institution">${esc(p.institution_name)} · ${esc(p.degree_level)} · ${esc(p.field)}</p></div><div class="score">${m?.overall_fit_score??"—"}<small>FIT SCORE</small></div></div><div class="badges"><span class="badge">${esc(p.verification_label||p.verification_status)}</span><span class="badge ${p.funding_status!=="verified"?"warning":""}">Funding: ${esc(p.funding_status)}</span><span class="badge">${esc(p.data_freshness)}</span></div><div class="facts"><div class="fact"><strong>Tuition</strong>${money(m?.sort_tuition_annual_usd)}</div><div class="fact"><strong>Deadline</strong>${esc(p.deadlines?.[0]?.date||"Needs verification")}</div><div class="fact"><strong>Evidence</strong>${m?.verified_field_count??0} fields verified</div></div><p class="explanation">${esc(r.explanation?.summary||"Review official source evidence.")}</p>${pend.map(d=>`<button class="text-button decide" data-id="${p.program_id}" data-field="${d.field}">Needs your decision: ${esc(d.field.replaceAll("_"," "))}</button>`).join("")}<div class="card-actions"><a class="secondary-button link-button" href="${esc(p.official_program_url)}" target="_blank" rel="noopener">Official program page ↗</a><button class="secondary-button favorite" data-id="${p.program_id}">${fs.has(p.program_id)?"★ Saved":"☆ Save favorite"}</button><label class="select-card"><input class="choose" data-id="${p.program_id}" type="checkbox" ${S.selected.has(p.program_id)?"checked":""}> Shortlist</label></div><details class="evidence"><summary>Evidence, sources & checklist</summary>${(p.sources||[]).map(s=>`<p><a href="${esc(s.final_url)}" target="_blank" rel="noopener">${esc(s.title||s.domain||"Official source")}</a> · ${esc(s.fetch_status)}</p>`).join("")||"<p>No source metadata available.</p>"}${(r.checklist?.items||[]).map(i=>`<p><strong>${esc(i.label)}:</strong> ${esc(i.value||"Needs verification")}</p>`).join("")}</details></article>`}).join(""):`<div class="empty">No results match these filters.</div>`;$("#shortlist-count").textContent=`${S.selected.size} selected`;$("#approve-shortlist").disabled=!S.selected.size||S.selected.size>8}
function event(e){const x=document.createElement("li");x.innerHTML=`<span class="trace-dot"></span><div><strong>${esc(e.stage||e.type)}</strong><span>${esc(e.summary||"Working…")}</span></div>`;$("#trace").append(x);$("#workflow-summary").textContent=e.summary||"Research in progress"}function stream(url){S.events?.close();$("#trace").innerHTML="";S.events=new EventSource(API+url);["job_started","agent_turn","agent_note","search_started","search_completed","page_fetched","page_failed","facts_extracted","extraction_failed","tool_rejected","gap_selected","prompt_injection_flagged","evidence_retrieved","program","program_updated","program_excluded","professor","professor_updated","warning","fallback_used","done","draft_created","draft_approved","email_send_started","email_sent","email_failed"].forEach(type=>S.events.addEventListener(type,e=>{try{event(JSON.parse(e.data))}catch{}}));S.events.onerror=()=>S.events?.close()}
async function snapshot(url){const x=await api(url);S.snap=x;$("#results-section").hidden=false;$("#source-badge").textContent=x.source_mode_label||x.source_mode;$("#warnings").innerHTML=(x.warnings||[]).map(w=>`<p>${esc(w)}</p>`).join("");render();if(!["completed","partial","fallback","failed"].includes(x.status))setTimeout(()=>snapshot(url),1800);else S.events?.close()}
$("#profile-form").onsubmit=async e=>{e.preventDefault();try{$("#form-error").textContent="";const p=profile();saveProfile();$("#research-button").disabled=true;$("#workflow-section").hidden=false;$("#results-section").hidden=true;S.selected.clear();S.job=await api("/api/research/programs",{method:"POST",body:JSON.stringify({profile:p,target_results:8})});if(S.job.events_url){stream(S.job.events_url);snapshot(S.job.snapshot_url)}else{S.snap=S.job;$("#results-section").hidden=false;$("#source-badge").textContent=S.snap.source_mode_label||S.snap.source_mode||"curated fallback";$("#warnings").innerHTML=(S.snap.warnings||[]).map(w=>`<p>${esc(w)}</p>`).join("");render();$("#workflow-summary").textContent="Live research unavailable; showing clearly labelled curated fallback."}}catch(x){$("#form-error").textContent=x.message}finally{$("#research-button").disabled=false}};
$("#clear-profile").onclick=()=>{try{localStorage.removeItem("gradbeacon-profile")}catch{}$("#profile-form").reset()};["#degree-filter","#funding-filter","#sort-results"].forEach(x=>$(x).onchange=render);$("#results").onchange=e=>{if(e.target.matches(".choose")){e.target.checked?S.selected.add(e.target.dataset.id):S.selected.delete(e.target.dataset.id);render()}};
$("#results").onclick=e=>{const f=e.target.closest(".favorite"),d=e.target.closest(".decide");if(f){const a=fav();a.has(f.dataset.id)?a.delete(f.dataset.id):a.add(f.dataset.id);saveFav(a);render()}if(d){const r=rows().find(x=>x.program.program_id===d.dataset.id),q=r?.pending_decisions?.find(x=>x.field===d.dataset.field);if(q){S.decision={id:d.dataset.id,field:d.dataset.field};$("#decision-question").textContent=q.question;$("#decision-sources").innerHTML=(q.suggested_sources||[]).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">Review official source ↗</a>`).join("")||"No additional safe source was found.";$("#decision-dialog").showModal()}}};
$("#continue-uncertain").onclick=async e=>{e.preventDefault();try{await api(`/api/research/${S.job.job_id}/programs/${S.decision.id}/decisions`,{method:"POST",body:JSON.stringify({field:S.decision.field,decision:"continue_with_uncertainty"})});$("#decision-dialog").close();snapshot(S.job.snapshot_url)}catch(x){alert(x.message)}};
$("#approve-shortlist").onclick=async()=>{try{await api(`/api/research/${S.job.job_id}/shortlist`,{method:"POST",body:JSON.stringify({program_ids:[...S.selected],acknowledge_uncertainty:true})});$("#professor-section").hidden=false}catch(x){alert(x.message)}};
$("#find-professors").onclick=async()=>{try{const i=list($("#profile-form").elements.interests.value);if(!i.length)throw Error("Add at least one research interest first.");S.pjob=await api("/api/research/professors",{method:"POST",body:JSON.stringify({job_id:S.job.job_id,program_ids:[...S.selected].slice(0,5),research_interests:i,max_results:8})});stream(S.pjob.events_url);pollProf(S.pjob.snapshot_url)}catch(x){alert(x.message)}};async function pollProf(url){try{const x=await api(url);prof(x.professors||[]);if(!["completed","partial","fallback","failed"].includes(x.status))setTimeout(()=>pollProf(url),1800);else S.events?.close()}catch(x){alert(x.message)}}
function val(x){return x?.value||"Not found"}function prof(a){$("#professor-results").innerHTML=a.length?a.map(p=>`<article class="card"><div class="card-top"><div><h3>${esc(p.name)}</h3><p class="institution">${esc(val(p.title))} · ${esc(p.institution)}</p></div><div class="score">${p.research_fit_score??"—"}<small>RESEARCH FIT</small></div></div><p class="explanation">${esc(p.research_fit_explanation||"Research fit needs verification.")}</p><p class="muted">${esc((p.research_interests||[]).map(val).join(" · "))}</p><div class="card-actions"><a class="secondary-button link-button" href="${esc(p.official_profile_url)}" target="_blank" rel="noopener">Official profile ↗</a>${p.official_email?`<button class="primary-button draft" data-id="${p.professor_id}">Draft outreach</button>`:`<span class="notice">No official email published</span>`}</div></article>`).join(""):`<div class="empty">No verified professor matches yet.</div>`}
$("#professor-results").onclick=async e=>{const b=e.target.closest(".draft");if(!b)return;try{const f=$("#profile-form"),email=prompt("Your email address (reply-to):");if(!email)return;openDraft(await api("/api/outreach/draft",{method:"POST",body:JSON.stringify({professor_job_id:S.pjob.professor_job_id,professor_id:b.dataset.id,program_id:[...S.selected][0]||null,student:{name:"Student",email,current_degree:f.qualification.value,institution:"Not provided",interests:list(f.interests.value),achievements:[],message_goal:"ask_about_research_fit"}})}))}catch(x){alert(x.message)}};
function openDraft(d){S.draft=d;$("#recipient").textContent=`Recipient: ${d.recipient_email} (official published address)`;$("#draft-subject").value=d.subject;$("#draft-text").value=d.body;$("#draft-reminders").innerHTML=(d.reminders||[]).map(x=>`<p>${esc(x)}</p>`).join("");$("#send-approval").checked=false;$("#send-button").disabled=true;$("#send-status").textContent="";$("#outreach-dialog").showModal()}$("#save-draft").onclick=async()=>{try{S.draft=await api(`/api/outreach/drafts/${S.draft.draft_id}`,{method:"PUT",body:JSON.stringify({subject:$("#draft-subject").value,body:$("#draft-text").value,expected_version:S.draft.version})});$("#send-status").textContent="Edits saved. Review the updated draft."}catch(x){$("#send-status").textContent=x.message}};$("#send-approval").onchange=e=>$("#send-button").disabled=!e.target.checked;$("#send-button").onclick=async()=>{try{if($("#draft-subject").value!==S.draft.subject||$("#draft-text").value!==S.draft.body)throw Error("Save edits before approval.");const t=prompt("Type exactly: I approve sending this email");if(t!=="I approve sending this email")throw Error("Confirmation text did not match.");const a=await api(`/api/outreach/drafts/${S.draft.draft_id}/approve`,{method:"POST",body:JSON.stringify({content_hash:S.draft.content_hash,confirm:true,confirmation_text:t})}),r=await api("/api/outreach/send",{method:"POST",body:JSON.stringify({draft_id:S.draft.draft_id,approval_token:a.approval_token})});$("#send-status").style.color="#18754c";$("#send-status").textContent=r.send_result?.message||`Email ${r.status}.`}catch(x){$("#send-status").style.color="#b42318";$("#send-status").textContent=x.message}};
async function health(){try{const h=await api("/health");$("#api-status").textContent=h.effective_mode==="live"?"Live research ready":`Mode: ${h.effective_mode}`}catch{$("#api-status").textContent="API unavailable"}}restore();health();
